/* Runtime for C generated by tools/m68k2c.py: 68000 instruction semantics with exact condition
 * codes (M68000 Programmer's Reference Manual, chapter 4). Game-independent.
 *
 * Generated functions use port.h's Cpu and memory accessors. Conventions:
 *   - on entry the return address is at (a7); `rts` pops it into c->ret and returns;
 *   - a call pushes the return address, calls, and continues only if c->ret is that address;
 *     otherwise the callee returned somewhere else (it dropped frames), so the caller returns
 *     too, and the first caller whose return address matches carries on.
 * Sizes are 1, 2 or 4 bytes. */
#ifndef M68K_RT_H
#define M68K_RT_H
#include <stdio.h>
#include <stdlib.h>
#include "port.h"

static inline uint32_t rt_mask(int sz) { return sz == 1 ? 0xFFu : sz == 2 ? 0xFFFFu : 0xFFFFFFFFu; }
static inline uint32_t rt_msb(int sz) { return sz == 1 ? 0x80u : sz == 2 ? 0x8000u : 0x80000000u; }
static inline uint32_t rt_sext(uint32_t v, int sz)
{
    return sz == 1 ? (uint32_t)(int32_t)(int8_t)v : sz == 2 ? (uint32_t)(int32_t)(int16_t)v : v;
}

/* registers: only the low byte or word changes for .b / .w */
static inline uint32_t rt_rd(uint32_t r, int sz) { return r & rt_mask(sz); }
static inline void rt_wr(uint32_t *r, int sz, uint32_t v)
{
    *r = sz == 4 ? v : (*r & ~rt_mask(sz)) | (v & rt_mask(sz));
}

/* memory by size */
static inline uint32_t rt_mrd(uint32_t a, int sz) { return sz == 1 ? rd8(a) : sz == 2 ? rd16(a) : rd32(a); }
static inline void rt_mwr(uint32_t a, int sz, uint32_t v)
{
    if (sz == 1) wr8(a, (uint8_t)v); else if (sz == 2) wr16(a, (uint16_t)v); else wr32(a, v);
}

/* condition codes */
static inline void rt_nz(Cpu *c, int sz, uint32_t r)
{
    r &= rt_mask(sz);
    c->ccr = (uint16_t)((c->ccr & ~(CC_N | CC_Z)) | (r & rt_msb(sz) ? CC_N : 0) | (r ? 0 : CC_Z));
}
static inline void rt_logic(Cpu *c, int sz, uint32_t r)      /* move, and, or, eor, not, tst, clr... */
{
    rt_nz(c, sz, r);
    c->ccr &= (uint16_t)~(CC_V | CC_C);
}

static inline uint32_t rt_add(Cpu *c, int sz, uint32_t s, uint32_t d)
{
    uint32_t m = rt_mask(sz), x = s & m, y = d & m, r = (x + y) & m;
    int carry = sz == 4 ? r < x : (x + y) > m;
    int v = ((x ^ r) & (y ^ r) & rt_msb(sz)) != 0;
    c->ccr = (uint16_t)((r & rt_msb(sz) ? CC_N : 0) | (r ? 0 : CC_Z) | (v ? CC_V : 0) | (carry ? CC_C | CC_X : 0));
    return r;
}
static inline uint32_t rt_sub(Cpu *c, int sz, uint32_t s, uint32_t d)
{
    uint32_t m = rt_mask(sz), x = s & m, y = d & m, r = (y - x) & m;
    int v = ((x ^ y) & (r ^ y) & rt_msb(sz)) != 0;
    c->ccr = (uint16_t)((r & rt_msb(sz) ? CC_N : 0) | (r ? 0 : CC_Z) | (v ? CC_V : 0) | (x > y ? CC_C | CC_X : 0));
    return r;
}
static inline void rt_cmp(Cpu *c, int sz, uint32_t s, uint32_t d)
{
    uint16_t x = c->ccr & CC_X;
    rt_sub(c, sz, s, d);
    c->ccr = (uint16_t)((c->ccr & ~CC_X) | x);
}
static inline uint32_t rt_addx(Cpu *c, int sz, uint32_t s, uint32_t d)
{
    uint32_t m = rt_mask(sz), x = s & m, y = d & m, xb = c->ccr & CC_X ? 1 : 0;
    uint64_t full = (uint64_t)x + y + xb;
    uint32_t r = (uint32_t)full & m;
    int carry = full > m;
    int v = ((x ^ r) & (y ^ r) & rt_msb(sz)) != 0;
    uint16_t z = r ? 0 : (c->ccr & CC_Z);                      /* Z cleared if nonzero, else kept */
    c->ccr = (uint16_t)((r & rt_msb(sz) ? CC_N : 0) | z | (v ? CC_V : 0) | (carry ? CC_C | CC_X : 0));
    return r;
}
static inline uint32_t rt_subx(Cpu *c, int sz, uint32_t s, uint32_t d)
{
    uint32_t m = rt_mask(sz), x = s & m, y = d & m, xb = c->ccr & CC_X ? 1 : 0;
    uint32_t r = (y - x - xb) & m;
    int borrow = (uint64_t)x + xb > y;
    int v = ((x ^ y) & (r ^ y) & rt_msb(sz)) != 0;
    uint16_t z = r ? 0 : (c->ccr & CC_Z);
    c->ccr = (uint16_t)((r & rt_msb(sz) ? CC_N : 0) | z | (v ? CC_V : 0) | (borrow ? CC_C | CC_X : 0));
    return r;
}
static inline uint32_t rt_neg(Cpu *c, int sz, uint32_t d) { return rt_sub(c, sz, d, 0); }
static inline uint32_t rt_negx(Cpu *c, int sz, uint32_t d) { return rt_subx(c, sz, d, 0); }

/* shifts and rotates by n (0-63); register counts are taken mod 64 by the caller */
enum { RT_ASL, RT_ASR, RT_LSL, RT_LSR, RT_ROL, RT_ROR, RT_ROXL, RT_ROXR };
static inline uint32_t rt_shift(Cpu *c, int kind, int sz, uint32_t v, unsigned n)
{
    int bits = sz * 8;
    uint32_t m = rt_mask(sz), r = v & m, msb = rt_msb(sz);
    int carry = 0, vflag = 0, x = c->ccr & CC_X ? 1 : 0;
    if (n == 0) {
        int cf = (kind == RT_ROXL || kind == RT_ROXR) ? x : 0;       /* roxl/roxr #0: C = X */
        c->ccr = (uint16_t)((c->ccr & CC_X) | (r & msb ? CC_N : 0) | (r ? 0 : CC_Z) | (cf ? CC_C : 0));
        return r;
    }
    for (unsigned i = 0; i < n; i++) {
        switch (kind) {
        case RT_ASL: case RT_LSL:
            carry = (r & msb) != 0; r = (r << 1) & m;
            if (kind == RT_ASL && ((r & msb) != 0) != carry) vflag = 1;
            x = carry; break;
        case RT_ASR: carry = r & 1; r = (r >> 1) | (r & msb); x = carry; break;
        case RT_LSR: carry = r & 1; r >>= 1; x = carry; break;
        case RT_ROL: carry = (r & msb) != 0; r = ((r << 1) | (uint32_t)carry) & m; break;
        case RT_ROR: carry = r & 1; r = (r >> 1) | (carry ? msb : 0); break;
        case RT_ROXL: carry = (r & msb) != 0; r = ((r << 1) | (uint32_t)x) & m; x = carry; break;
        case RT_ROXR: carry = r & 1; r = (r >> 1) | (x ? msb : 0); x = carry; break;
        }
    }
    (void)bits;
    uint16_t xf = (kind == RT_ROL || kind == RT_ROR) ? (c->ccr & CC_X) : (x ? CC_X : 0);
    c->ccr = (uint16_t)(xf | (r & msb ? CC_N : 0) | (r ? 0 : CC_Z) | (vflag ? CC_V : 0) | (carry ? CC_C : 0));
    return r;
}

/* the 16 conditions of Bcc / DBcc / Scc */
static inline int rt_cond(const Cpu *c, int cc)
{
    int C = c->ccr & CC_C ? 1 : 0, V = c->ccr & CC_V ? 1 : 0, Z = c->ccr & CC_Z ? 1 : 0, N = c->ccr & CC_N ? 1 : 0;
    switch (cc) {
    case 0: return 1;               case 1: return 0;              /* t, f */
    case 2: return !C && !Z;        case 3: return C || Z;         /* hi, ls */
    case 4: return !C;              case 5: return C;              /* cc, cs */
    case 6: return !Z;              case 7: return Z;              /* ne, eq */
    case 8: return !V;              case 9: return V;              /* vc, vs */
    case 10: return !N;             case 11: return N;             /* pl, mi */
    case 12: return N == V;         case 13: return N != V;        /* ge, lt */
    case 14: return !Z && N == V;   case 15: return Z || N != V;   /* gt, le */
    }
    return 0;
}

/* bit operations: Z = the bit was clear; registers use bit mod 32, memory mod 8 */
static inline void rt_btst(Cpu *c, uint32_t v, unsigned bit)
{
    c->ccr = (uint16_t)((c->ccr & ~CC_Z) | (v >> bit & 1 ? 0 : CC_Z));
}

static inline uint32_t rt_ext(Cpu *c, int to, uint32_t r)       /* ext.w (to 2) / ext.l (to 4) */
{
    uint32_t v = to == 2 ? rt_sext(r, 1) & 0xFFFF : rt_sext(r, 2);
    rt_logic(c, to, v);
    return to == 2 ? (r & 0xFFFF0000u) | v : v;
}

static inline uint32_t rt_mulu(Cpu *c, uint32_t s, uint32_t d)
{
    uint32_t r = (s & 0xFFFF) * (d & 0xFFFF); rt_logic(c, 4, r); return r;
}
static inline uint32_t rt_muls(Cpu *c, uint32_t s, uint32_t d)
{
    uint32_t r = (uint32_t)((int32_t)(int16_t)s * (int32_t)(int16_t)d); rt_logic(c, 4, r); return r;
}
static inline uint32_t rt_divu(Cpu *c, uint32_t s, uint32_t d)
{
    uint32_t q, rem, div = s & 0xFFFF;
    if (!div) { fprintf(stderr, "m68k_rt: divide by zero\n"); abort(); }
    q = d / div; rem = d % div;
    /* overflow leaves the register and N, Z, C alone and sets V (Musashi, the reference) */
    if (q > 0xFFFF) { c->ccr |= CC_V; return d; }
    c->ccr = (uint16_t)((c->ccr & CC_X) | (q & 0x8000 ? CC_N : 0) | (q ? 0 : CC_Z));
    return rem << 16 | q;
}
static inline uint32_t rt_divs(Cpu *c, uint32_t s, uint32_t d)
{
    int32_t div = (int16_t)s, dv = (int32_t)d;
    if (!div) { fprintf(stderr, "m68k_rt: divide by zero\n"); abort(); }
    if (d == 0x80000000u && div == -1) { c->ccr = (uint16_t)((c->ccr & CC_X) | CC_Z); return 0; }
    int32_t q = dv / div, rem = dv % div;
    if (q > 32767 || q < -32768) { c->ccr |= CC_V; return d; }
    c->ccr = (uint16_t)((c->ccr & CC_X) | (q & 0x8000 ? CC_N : 0) | ((q & 0xFFFF) ? 0 : CC_Z));
    return (uint32_t)(rem & 0xFFFF) << 16 | (uint32_t)(q & 0xFFFF);
}

/* the stack and calls */
static inline void rt_push(Cpu *c, uint32_t v) { c->a[7] -= 4; wr32(c->a[7], v); }
static inline void rt_rts(Cpu *c) { c->ret = rd32(c->a[7]); c->a[7] += 4; }

/* indirect calls and jumps: implemented in the generated registry (every generated entry,
 * and the hand ports); returns 0 if the address is not a known entry */
int rt_dispatch(Cpu *c, uint32_t target);
void rt_unknown(uint32_t from, uint32_t target);
/* a call or jump to code with no translation: provided by the host. The harness hands control
 * back to the 68000 at `target` (c->ret = target; the generated callers unwind); a native build,
 * where everything is translated, stops. */
void rt_leave(Cpu *c, uint32_t from, uint32_t target);
/* After a hand port (called with c->ret = 0): it returned, so do the original's rts; or it set
 * c->ret to carry on in the original's code there (with the stack as it left it), as the original
 * does when it jumps away instead of returning (port/world.h, port_continue_at). */
static inline void rt_after_hand(Cpu *c)
{
    if (!c->ret) { rt_rts(c); return; }
    uint32_t t = c->ret;
    if (t & 0x80000000u) { rt_leave(c, 0, t & 0xFFFFFF); return; }   /* port_leave_to_68k (world.h) */
    if (!rt_dispatch(c, t)) rt_leave(c, 0, t);
}
/* native build: generated code calls this at a poll point (a loop waiting for an interrupt,
 * analysis/native.json "poll"); the host runs a frame and the interrupt there */
void rt_poll(Cpu *c, uint32_t at);

/* native build, optional timing (analysis/native.json "cycles"): each instruction charges its
 * 68000 cycles to the current slice. When the slice is used up, or the status register changed
 * (the interrupt mask), the host's rt_slice advances time (scanlines, sound, the VBlank
 * interrupt) and returns; `next` is where execution goes on, for an interrupt's return address. */
extern int32_t rt_budget;
extern int rt_irq_check;
void rt_slice(Cpu *c, uint32_t next);
void rt_set_sr(Cpu *c, uint16_t sr);
#define RT_CYC(n, next) do { rt_budget -= (int32_t)(n); if (rt_budget <= 0 || rt_irq_check) rt_slice(c, (next)); } while (0)

/* MULU / MULS timing on the 68000, as Musashi counts it: 2 cycles per one bit of the source,
 * or per change between neighbouring bits of the sign-extended source */
static inline int rt_mulu_cyc(uint32_t s)
{
    int n = 0;
    for (uint32_t y = s & 0xFFFF; y; y >>= 1) if (y & 1) n += 2;
    return n;
}
static inline int rt_muls_cyc(uint32_t s)
{
    int n = 0; uint32_t f = 0;
    for (uint32_t y = (uint32_t)(int32_t)(int16_t)(s & 0xFFFF); y; y >>= 1)
        if ((y & 1) != f) { n += 2; f = 1 - f; }
    return n;
}

/* watchdog: every branch target in generated code passes here. Translated code takes no
 * emulated time, so a loop that waits for time or an interrupt never ends; after rt_limit passes
 * in one call the host's rt_stuck reports the recent branch targets (a ring of 16). */
extern uint32_t rt_ring[16]; extern unsigned rt_ring_i; extern unsigned long rt_steps, rt_limit;
void rt_stuck(void);
#ifdef RT_TRACE    /* measuring which translated code still runs: every label reached, kept by the host */
extern unsigned char rt_seen[0x40000];
#define RT_AT(a) do { rt_seen[((a) >> 1) & 0x3FFFF] = 1; rt_ring[rt_ring_i++ & 15] = (a); if (++rt_steps > rt_limit) rt_stuck(); } while (0)
#else
#define RT_AT(a) do { rt_ring[rt_ring_i++ & 15] = (a); if (++rt_steps > rt_limit) rt_stuck(); } while (0)
#endif

#endif
